services = list_services({})

per_service = for svc in services {
    first = search_logs({ service: svc, level: "ERROR", page: 1 })
    rest_pages = for p in list.range(2, first.total_pages + 1) {
        r = search_logs({ service: svc, level: "ERROR", page: p })
        return r.items
    }
    all_items = fold acc = first.items for pg in rest_pages { return acc + pg }
    ts_list = list.sort(for it in all_items { return time.parse(it.ts) })
    n = list.length(ts_list)
    burst = fold acc = { count: 0, start: 0 } for i in list.range(0, n) {
        t0 = ts_list[i]
        window_end = t0 + 600000
        cnt = fold c = 0 for t in list.slice(ts_list, i) {
            return c + (1 if t < window_end else 0)
        }
        return { count: cnt, start: t0 } if cnt > acc.count else acc
    }
    return { service: svc, total: n, burst_count: burst.count, spike_start: burst.start }
}

best = fold acc = null for row in per_service {
    return row if acc == null or row.burst_count > acc.burst_count else acc
}
assert(best != null and best.burst_count > 0, "no error spike found")

deploys = get_deploys({ service: best.service })
parsed = for d in deploys { return { sha: d.sha, at: time.parse(d.deployed_at) } }
before = for d in parsed { skip if d.at > best.spike_start; return d }
candidates = list.sort_by(before, "at") if before != [] else list.sort_by(parsed, "at")
chosen = candidates[list.length(candidates) - 1]

owner = get_service_owners({ service: best.service })

res = submit_result({ answer: { service: best.service, deploy_sha: chosen.sha, owner_email: owner.owner_email } })
return { submitted: res.recorded, service: best.service, burst_count: best.burst_count, spike_start: time.format(best.spike_start), deploy_sha: chosen.sha, owner: owner.owner_email }

